const $ = (s) => document.querySelector(s);
const wa = (t) =>
  `https://wa.me/${WHATSAPP}?text=${encodeURIComponent(t || "Hello Innomass, I would like a solar quote.")}`;
document.querySelectorAll("[data-wa]").forEach((a) => (a.href = wa()));
$("#svc").innerHTML = SERVICES.map(
  (s) =>
    `<div class="card svc"><div class="ic">${s[0]}</div><h3>${s[1]}</h3><p>${s[2]}</p><a href="${wa("Hello Innomass, I need this service: " + s[1])}">Request this service</a></div>`,
).join("");
$("#whyc").innerHTML = WHY.map(
  (w) =>
    `<div class="card"><div class="body"><span class="tag">✓ Our promise</span><h3>${w[0]}</h3><p>${w[1]}</p></div></div>`,
).join("");
let cur = "All";
function drawProds() {
  $("#filters").innerHTML = CATS.map(
    (c) => `<button aria-pressed="${c === cur}" data-c="${c}">${c}</button>`,
  ).join("");
  $("#prods").innerHTML = PRODUCTS.filter((p) => cur === "All" || p.c === cur)
    .map(
      (p) =>
        `<div class="card"><div class="art">${p.img ? `<img src="${p.img}" alt="${p.n}" loading="lazy">` : `<svg viewBox="0 0 200 170" width="70%" role="img" aria-label="${p.n}">${ART[p.i]}</svg>`}</div><div class="body"><span class="tag">${p.c}</span><h3>${p.n}</h3><p>${p.d}</p><a class="btn btn-o" href="${wa("Hello Innomass, please send me the price for: " + p.n)}">Request price</a></div></div>`,
    )
    .join("");
  document.querySelectorAll("#filters button").forEach(
    (b) =>
      (b.onclick = () => {
        cur = b.dataset.c;
        drawProds();
      }),
  );
}
drawProds();
const N = (v) => "₦" + Math.round(v).toLocaleString("en-NG");
function calc() {
  const s = +$("#spend").value || 0;
  $("#rs").textContent = N(s * 0.7);
  $("#ry").textContent = N(s * 0.7 * 12);
  $("#rk").textContent =
    s < 30000
      ? "1.5 kVA"
      : s < 80000
        ? "3.5 kVA"
        : s < 150000
          ? "5 kVA"
          : s < 300000
            ? "10 kVA"
            : "15 kVA or more";
}
$("#spend").oninput = calc;
calc();
$("#menu").onclick = (e) => {
  const o = $("#links").classList.toggle("open");
  e.target.setAttribute("aria-expanded", o);
};
$("#links").onclick = () => $("#links").classList.remove("open");
$("#qf").onsubmit = (e) => {
  e.preventDefault();
  const f = new FormData(e.target);
  const m = `Quote request\nName: ${f.get("n")}\nPhone: ${f.get("p")}\nProperty: ${f.get("t")}\nAppliances: ${f.get("a")}\nMonthly spend: ${f.get("s")}`;
  $("#ok").style.display = "block";
  window.open(wa(m), "_blank");
};
